#include <bits/stdc++.h>
#include <gmpxx.h>
using namespace std;
static string pal(string h,int n){string a=h;for(int j=n/2-1;j>=0;j--)a+=h[j];return a;}
static mpz_class dist(const mpz_class& n,const string&s){int len=s.size(),pref=(len+1)/2;mpz_class x(s.substr(0,pref),10),best=-1;auto consider=[&](const string& t){if(t.empty()||t[0]=='0')return;mpz_class z(t,10);mpz_class diff=n-z;if(diff<0)diff=-diff;if(best<0||diff<best)best=diff;};for(int delta=-1;delta<=1;delta++){mpz_class p=x+delta;if(p<0)continue;string h=p.get_str();if((int)h.size()==pref)consider(pal(h,len));}if(len>1)consider(string(len-1,'9'));consider("1"+string(len-1,'0')+"1");return best;}
int main(int argc,char**argv){int steps=20000,stride=128;mpz_class n(argc>1?string(argv[1]):string("196"),10);vector<mpz_class> g(stride+1);long long bad=0,palnum=0;int maxdef=-1,tmax=-1;vector<int> length(steps+1),exps(steps+1);for(int t=0;t<=steps;t++){string s=n.get_str();length[t]=s.size();if(equal(s.begin(),s.end(),s.rbegin()))palnum++;mpz_class gap=dist(n,s);string gs=gap.get_str();exps[t]=gs.size()-1;int deficit=(int)s.size()/2-exps[t];if(deficit>maxdef){maxdef=deficit;tmax=t;}if(t>=stride && gap<=g[t%(stride+1)])bad++;g[t%(stride+1)]=gap;if(t==0 || t==12877 || t==20000)cout<<t<<" digits="<<s.size()<<" exp="<<exps[t]<<" deficit="<<deficit<<" margin_top="<<gs.substr(0,min((size_t)16,gs.size()))<<"\n";if(t==steps)break;string rev(s.rbegin(),s.rend());mpz_class x(rev,10);n+=x;}
int ming=999,minex=999;for(int t=0;t+stride<=steps;t++){ming=min(ming,length[t+stride]/2-length[t]/2);minex=min(minex,exps[t+stride]-exps[t]);}cout<<"SUMMARY palindrome="<<palnum<<" bad_stride="<<bad<<" max_def="<<maxdef<<" max_def_time="<<tmax<<" min_half_length_growth="<<ming<<" min_gap_exp_growth="<<minex<<"\n";}